pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // 1. Domain: caller must be the current owner for the reference to succeed; otherwise the reference reverts.
        //    We want the property to hold for ALL inputs, so we restrict to the domain where the operation is expected to succeed in the reference.
        vm.assume(caller == c.owner());

        // 2. Execute
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // 3. Assert: ownership transferred to newOwner
        assertTrue(c.owner() == newOwner);
    }
}

