pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address targetOwner) public {
        vm.assume(actor != address(0));
        vm.assume(targetOwner != actor);

        // Set the stage: the original owner (test contract itself) transfers ownership to actor
        c.transferOwnership(actor);

        // Now actor attempts to transfer ownership to targetOwner
        vm.prank(actor);
        c.transferOwnership(targetOwner);

        // Assert: owner must still be actor (since only the current owner can transfer)
        assertTrue(c.owner() == actor);
    }
}

