pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        // nonOwner must not be the current owner
        vm.assume(nonOwner != c.owner());
        // fuzz the new owner as well, no further restrictions beyond address validity
        vm.prank(nonOwner);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference must revert (ok == false); the bug succeeds (ok == true).
        // Because a revert leaves owner unchanged and a succeed sets owner == newOwner,
        // we assert that owner is STILL the deployer (initial owner).
        assertTrue(c.owner() == address(this));
    }
}

