import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address caller) public {
        vm.assume(owner != address(0));
        vm.prank(owner);
        c.transferOwnership(owner);
        bool success;
