pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set a known owner so the reference can distinguish owner vs non-owner
        c.transferOwnership(address(this));
    }
    function testFuzz_property(address caller) public {
        // owner is already set; caller is the fuzzed input
        vm.assume(caller != address(this)); // we test non-owner separately from owner

        // Test non-owner: reference must revert, bug must also revert (so behaviour matches here)
        bool nonOwnerRevert;
        vm.prank(caller);
        try c.owned() {
            nonOwnerRevert = false;
        } catch {
            nonOwnerRevert = true;
        }

        // Test owner: reference must NOT revert, bug MUST revert
        bool ownerRevert;
        vm.prank(address(this));
        try c.owned() {
            ownerRevert = false;
        } catch {
            ownerRevert = true;
        }

        // Universal property: owned() reverts exactly when caller is not the owner.
        // For non-owner we expect revert (true), for owner we expect no-revert (false).
        // The bug breaks this because ownerRevert will be true.
        assertTrue(nonOwnerRevert && !ownerRevert);
    }
}

