pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address caller) public {
        vm.assume(owner != address(0));
        vm.assume(caller != owner);
        vm.prank(owner);
        c.transferOwnership(owner);
        bool ok;
        vm.prank(caller);
        try c.owned() { ok = true; } catch { ok = false; }
        // When caller is not the owner, reference contract reverts, so ok should be false.
        // Buggy contract also reverts, so no discrepancy here.
        // The real discrepancy: owner call always succeeds in reference, always reverts in buggy.
        bool ownerOk;
        vm.prank(owner);
        try c.owned() { ownerOk = true; } catch { ownerOk = false; }
        assertTrue(ownerOk);
    }
}

